corrected_code:
const express = require('express');
const { WireTransferService } = require('../services/treasury');

const app = express();
const treasuryApp = express({ mergeParams: true });

app.use('/banking/org/:orgId/treasury', (req, res, next) => {
  if (!req.session || !req.session.orgId) {
    return res.status(401).json({ error: 'Treasury authentication required' });
  }

  // Enforce that caller's session organization matches the URL organization path
  if (req.session.orgId !== req.params.orgId) {
    return res.status(403).json({ error: 'Access denied: organization mismatch' });
  }
  next();
}, treasuryApp);

treasuryApp.get('/wires/:wireId', async (req, res) => {
  // Wire transfer lookup strictly scoped to the authenticated organization
  const wire = await WireTransferService.getTransferScoped({
    wireId: req.params.wireId,
    orgId: req.params.orgId
  });

  if (!wire) {
    return res.status(404).json({ error: 'Wire transfer not found or unauthorized' });
  }

  res.json({
    wireId: wire.id,
    originAccount: wire.sourceIban,
    beneficiaryAccount: wire.destinationIban,
    amount: wire.amount,
    currency: wire.currency,
    clearingStatus: wire.status
  });
});

app.listen(8443);
